fn pad2(x: i32, y: i32, v: i32, rgb: i32, sc: i32) {
    if v < 10 {
        host::display::draw_number(x, y, 0, rgb, sc);
        host::display::draw_number(x + sc * 8, y, v, rgb, sc);
    } else {
        host::display::draw_number(x, y, v, rgb, sc);
    }
}

fn cellbox(x: i32, y: i32, cw: i32, chh: i32) {
    host::display::fill_rect(x, y, cw, chh, 0x2a2a34);
    host::display::fill_rect(x + 2, y + 2, cw - 4, chh - 4, 0x101016);
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let mut rem: i32 = 3 * 86400 - t / 60;
    if rem < 0 { rem = 0; }
    let d: i32 = rem / 86400;
    let hh: i32 = (rem / 3600) % 24;
    let mm: i32 = (rem / 60) % 60;
    let ss: i32 = rem % 60;
    host::display::clear(0x06060a);
    host::display::draw_string(20, 20, "T MINUS", 0x808080, 2);
    let cw: i32 = (w - 60) / 4;
    let y: i32 = h / 2 - 50;
    cellbox(12, y, cw, 70);
    pad2(12 + 10, y + 14, d, 0xffffff, 3);
    host::display::draw_string(12 + 8, y + 76, "DAYS", 0x808080, 1);
    cellbox(24 + cw, y, cw, 70);
    pad2(24 + cw + 10, y + 14, hh, 0xffffff, 3);
    host::display::draw_string(24 + cw + 8, y + 76, "HRS", 0x808080, 1);
    cellbox(36 + cw * 2, y, cw, 70);
    pad2(36 + cw * 2 + 10, y + 14, mm, 0xffffff, 3);
    host::display::draw_string(36 + cw * 2 + 8, y + 76, "MIN", 0x808080, 1);
    cellbox(48 + cw * 3, y, cw, 70);
    pad2(48 + cw * 3 + 10, y + 14, ss, 0xffffff, 3);
    host::display::draw_string(48 + cw * 3 + 8, y + 76, "SEC", 0x808080, 1);
    if rem == 0 && (t / 10) % 2 == 0 {
        host::display::draw_string(20, y + 110, "LIFTOFF", 0xffd040, 4);
    }
    host::display::present();
}
